-- PPh21 TER 월별 실효세율 125구간 시드 (PMK 168/2023 Lampiran, 2026-08-30)
--
-- 목적: MASTER 가 /admin/tax-rates 에서 TER 표를 "보고 수정" 할 수 있게
-- tax_rate_config 로 편입. TS 상수(config/pph21-ter-rates.ts)는 언제나
-- fallback baseline — DB 행이 없거나 sanity 실패 시 TS 로 복귀하므로
-- 이 시드/편집이 계산을 깨뜨릴 수 없다 (rate-provider resolveTER).
-- 이 SQL 은 scripts 가 아닌 TS 표에서 기계 생성됨 (수기 오타 불가).

DELETE FROM tax_rate_config WHERE category IN ('PPH21_TER_A','PPH21_TER_B','PPH21_TER_C');
